import { developmentMailDirectory } from '../configurations/development-mail';

export const MAIL_KEY_ERROR =
  'MAIL_OUTBOX_KEY must be a base64 32-byte key (value redacted)';

// AES-256-GCM key for queued mail payloads (raw token, recipient). Generated by
// `pnpm mail:keys`; the API and the worker must use the same value. A present
// but malformed key throws (redacted); an absent key means mail is not ready.
export function mailOutboxKey(env: NodeJS.ProcessEnv = process.env) {
  const value = env.MAIL_OUTBOX_KEY?.trim();
  if (!value) return null;
  if (
    !/^[A-Za-z0-9+/]{43}=$/.test(value) ||
    Buffer.from(value, 'base64').length !== 32
  )
    throw new Error(MAIL_KEY_ERROR);
  return Buffer.from(value, 'base64');
}

// The provider transport: private development files (never in production) or
// Resend with an API key and sender.
export function mailTransportReady(env: NodeJS.ProcessEnv = process.env) {
  if (env.MAIL_MODE === 'file') return Boolean(developmentMailDirectory());
  return Boolean(
    env.MAIL_MODE === 'resend' && env.RESEND_API_KEY && env.MAIL_FROM
  );
}

// Links in mails point at WEB_ORIGIN (https in production).
export function mailWebOrigin(env: NodeJS.ProcessEnv = process.env) {
  const origin = env.WEB_ORIGIN;
  if (!origin) return null;
  try {
    const url = new URL(origin);
    if (
      url.origin !== origin ||
      !['http:', 'https:'].includes(url.protocol) ||
      (env.NODE_ENV === 'production' && url.protocol !== 'https:')
    )
      return null;
    return origin;
  } catch {
    return null;
  }
}

/** Mail can be queued and delivered: transport, link origin and payload key. */
export function mailConfigured(env: NodeJS.ProcessEnv = process.env) {
  try {
    return Boolean(
      mailTransportReady(env) && mailWebOrigin(env) && mailOutboxKey(env)
    );
  } catch {
    return false;
  }
}
